parameters.jsCode:
// Extrait le 1er numero francais trouve dans le body de l'email recu (signature usuelle)
const text = $('Code_parse_gmail').item.json.text || '';
const phoneRegex = /(?:(?:\+33|0033)\s?[1-9]|0[1-9])(?:[\s.\-]?\d{2}){4}/g;
const matches = text.match(phoneRegex);
let phone = matches && matches[0] ? matches[0] : null;
if (phone) {
  phone = phone.replace(/[\s.\-]/g, '');
  if (phone.startsWith('+33')) phone = '0' + phone.slice(3);
  if (phone.startsWith('0033')) phone = '0' + phone.slice(4);
}
return { ...$json, extracted_manager_phone: phone };

